<?php require_once 'config.php'; require_login();
if(isset($_GET['approve']) && is_admin()){ $pdo->prepare("UPDATE expenses SET status='approved',approved_by=?,approved_at=NOW() WHERE id=?")->execute([$_SESSION['user_id'],$_GET['approve']]); header('Location: expenses.php'); exit; }
if(isset($_GET['reject']) && is_admin()){ $pdo->prepare("UPDATE expenses SET status='rejected',approved_by=?,approved_at=NOW() WHERE id=?")->execute([$_SESSION['user_id'],$_GET['reject']]); header('Location: expenses.php'); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 $file=null; if(!empty($_FILES['receipt']['name'])){ $ext=pathinfo($_FILES['receipt']['name'],PATHINFO_EXTENSION); $file='expense_'.time().'_'.rand(1000,9999).'.'.$ext; move_uploaded_file($_FILES['receipt']['tmp_name'],'uploads/'.$file); }
 $pdo->prepare('INSERT INTO expenses(paid_by,category_id,amount,currency,expense_date,description,receipt_file) VALUES(?,?,?,?,?,?,?)')->execute([$_SESSION['user_id'],$_POST['category_id'],$_POST['amount'],$_POST['currency'],$_POST['expense_date'],$_POST['description'],$file]); header('Location: expenses.php'); exit;
}
$cats=$pdo->query("SELECT * FROM categories WHERE type='expense' ORDER BY name")->fetchAll();
$rows=$pdo->query("SELECT e.*,u.name user,c.name cat FROM expenses e JOIN users u ON u.id=e.paid_by LEFT JOIN categories c ON c.id=e.category_id ORDER BY e.id DESC")->fetchAll();
include 'includes/header.php'; ?>
<h1>Expenses</h1><div class="card"><h3>Add Expense</h3><form method="post" enctype="multipart/form-data"><div class="grid"><div><label>Category</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></div><div><label>Amount</label><input name="amount" type="number" step="0.01" required></div><div><label>Currency</label><input name="currency" value="EGP"></div><div><label>Date</label><input name="expense_date" type="date" value="<?=date('Y-m-d')?>" required></div></div><label>Description</label><textarea name="description"></textarea><label>Receipt</label><input type="file" name="receipt"><button>Submit Expense</button></form></div>
<div class="card"><h3>Expense List</h3><table><tr><th>Date</th><th>Partner</th><th>Category</th><th>Amount</th><th>Status</th><th>Receipt</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['expense_date'])?></td><td><?=h($r['user'])?></td><td><?=h($r['cat'])?></td><td><?=number_format($r['amount'],2).' '.h($r['currency'])?></td><td><span class="status <?=$r['status']?>"><?=h($r['status'])?></span></td><td><?php if($r['receipt_file']):?><a class="btn secondary" href="uploads/<?=h($r['receipt_file'])?>" target="_blank">Open</a><?php endif;?></td><td class="actions"><?php if(is_admin() && $r['status']=='pending'):?><a class="btn ok" href="?approve=<?=$r['id']?>">Approve</a><a class="btn danger" href="?reject=<?=$r['id']?>">Reject</a><?php endif;?></td></tr><?php endforeach;?></table></div>
<?php include 'includes/footer.php'; ?>
